  "input": {
    "brief": "为小团队做一个无需登录、无需网络的单页费用记录页：填写描述、金额并选择“办公/差旅”后添加记录，支持删除及“全部/办公/差旅”筛选，准确显示全部费用总额和当前筛选小计；金额只接受0.01至9999.99元（含边界）、最多两位小数，无效金额或空白描述应提示且不得入账，数据仅在当前页面保存。",
    "capability": "offline-single-html",
    "mode": "live",
    "verifierEngine": "llm-rubric",
    "implementationEvidencePolicy": "legacy",
    "acceptanceStrategy": "planned-groups-v1",
